/* From Uiverse.io by Deri-Kurniawan  - Tags: button, colorful, btn, hover effect */
.__UIV_SCOPE__ .button {
  position: relative;
  cursor: pointer;
  padding: 6px 6px;
  position: relative;
  background: linear-gradient(
    75deg,
    rgba(192, 97, 237, 0.8),
    rgba(255, 255, 255, 0.4),
    rgba(255, 255, 255, 0.4),
    rgba(252, 144, 98, 0.8),
    rgba(252, 144, 98, 0.8),
    rgba(255, 255, 255, 0.4),
    rgba(228, 89, 199, 0.8),
    rgba(255, 255, 255, 0.4),
    rgba(228, 89, 199, 0.8)
  );
  border: 1.5px solid transparent;
  border-radius: 12px;
  inset: 0;
}

.__UIV_SCOPE__ .button .light-border {
  padding: 8px 24px;
  border: 0.1px solid rgba(255, 255, 255, 0.4);
  border-radius: 8px;
  pointer-events: none;
  transition: all 0.3s ease-in-out;
  box-shadow: 0 0 20px rgba(255, 255, 255, 0.8);
}

.__UIV_SCOPE__ .button:hover {
  filter: contrast(1.2) brightness(1.2);
  box-shadow: 0 0 20px rgba(255, 255, 255, 0.8);
  transition: all 0.3s ease-in-out;
}
